import{z as i,x as n,o as A,c as s,q as e,j as B,D as a,d as t,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"自改进回路的解剖","description":"","frontmatter":{"title":"自改进回路的解剖","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-improvement-loop.md","filePath":"llm/self-improvement-loop.md","lastUpdated":1791413859000}'),p={name:"llm/self-improvement-loop.md"};function m(F,E,d,h,_,D){const l=n("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="自改进回路的解剖" tabindex="-1">自改进回路的解剖 <a class="header-anchor" href="#自改进回路的解剖" aria-label="Permalink to &quot;自改进回路的解剖&quot;">​</a></h1><div class="epigraph"><p>自训练不是没有数据，而是把数据的来源从人换成模型自己的输出；回路每转一圈都是一次再采样，资产与损耗必须分开记账。</p><footer>—— 据 Zelikman 等 STaR；Gulcehre 等 ReST-EM 整理</footer></div><p><a href="/llm/reasoning-faithfulness">上一课</a>把链的可信性问题收在「强化学习进阶」课末：测量要靠偏置测试与链干预，可监视性、必要性、忠实性三件不同，监视器进了奖励还会混淆链。监督信号本身不可靠，正是本课程「自训练与数据闭环」的出发点：与其继续加重人类标注，不如让模型的输出直接进入训练——生成、过滤或验证、训练、再生成。本课解剖这条回路：每一站什么是资产、什么是损耗。<a href="/llm/rlvr">RLVR</a>与<a href="/llm/self-play-lm">自博弈</a>已把单点机制讲过，<a href="/llm/rft-data-loop">拒绝采样数据循环</a>给过单轮版本，这里只立全回路的骨架。本单元后面的停止条件、坍缩实证、验证器瓶颈、RLVR 设计与合成课程，都默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>人类示范与标注有三条硬上限：预算、覆盖、以及天花板——超过示范者的能力无法被示范。可验证域（数学、代码）里，模型的输出自带可核对的候选，于是「训练数据」可以自产：每题采样多条，留下通过验证的那些。缺口不在会不会调用生成接口，而在回路本身：把输出变成信号要四个环节接力，任何一环的系统性偏差都不会被下一环抵消，只会被再生成环节放大。单轮 RFT 是一次过滤采样；多轮闭环是把同一个选择算子反复作用在策略分布上——两者性质不同：前者近似「换一批更好的离线数据」，后者是分布的迭代映射，收敛到哪、变窄到什么程度，都由回路结构决定。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',6)),(A(),B(o,null,{default:a(()=>[r(l,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%EF%BC%9A%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%E6%AF%8F%E9%A2%98%E9%87%87%E6%A0%B7%20K%20%E6%9D%A1%22%5D%20--%3E%20FIL%5B%22%E8%BF%87%E6%BB%A4%E4%B8%8E%E9%AA%8C%E8%AF%81%EF%BC%9Av(x%2C%20y)%E3%80%81%E8%A7%84%E5%88%99%E6%88%96%E9%87%91%E6%A0%87%22%5D%0A%20%20FIL%20--%3E%20TRN%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E9%80%9A%E8%BF%87%E8%80%85%E5%81%9A%20SFT%EF%BC%8C%E6%88%96%E5%85%A8%E4%BD%93%E6%8C%89%E5%A5%96%E5%8A%B1%E5%81%9A%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20TRN%20--%3E%20NEW%5B%22%E6%96%B0%E5%88%86%E5%B8%83%22%5D%0A%20%20NEW%20--%3E%20GEN%0A%20%20MON%5B%22%E4%BB%AA%E8%A1%A8%EF%BC%9A%E9%80%9A%E8%BF%87%E7%8E%87%E3%80%81%E6%96%B0%E9%A2%96%E5%BA%A6%E3%80%81%E5%A4%9A%E6%A0%B7%E6%80%A7%22%5D%20--%3E%20DEC%7B%22%E7%BB%A7%E7%BB%AD%E4%B8%80%E8%BD%AE%EF%BC%9F%22%7D%0A%20%20NEW%20--%3E%20MON%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p>生成站要多样性而非一致性：温度、提示变体、多路径采样。过滤验证站是选择算子，\\(v(x,y)\\) 来自程序或金标比对。训练站两种接法：对通过者做 SFT（STaR、RFT、ReST-EM 一族），或对全体样本按奖励做策略梯度——<a href="/llm/rlvr">RLVR</a> 把四站焊进一个训练步，SFT 循环则摊成多个迭代。再生成站的关键事实：新策略的分布移了，上一轮的数据不再 on-policy。</p><p><span class="marginnote">「选择算子」就是那条只有及格线没有感情的规则：拿到一对（题目，回答），通过就留下，不通过就扔。它可以是一段单元测试、一个答案比对脚本，也可以是另一个模型——关键在于它做的是硬性筛选，不是打分排序。</span></p><p>资产三项：on-policy 覆盖——训练分布与当前策略的失败模式对齐，这是相对静态示范的根本优势；通过验证的解法是可复用的确定性资产；失败样本在策略梯度下是负信号来源。损耗三项：过滤是收缩算子，多样性逐轮下降；验证误差会被优化压力放大；覆盖收缩到「会一半」的题上，全对与全错组都没有梯度（<a href="/llm/group-relative-baseline">群体相对基线</a>课的结论）。</p><p><span class="marginnote">数字实例：每题采 16 条，通过 4 条，淘汰率 75%；一万题一轮最多攒下 4 万条已验证解法。但某题若 16 条全对或全错，它这一轮贡献的梯度接近零——覆盖向「会一半」的题集中，就是这道算术在逐轮放大。</span></p><p><span class="marginnote">ReST-EM 的实证口径：迭代两三轮后收益已显著递减——回路不是永动机，每轮的边际增量在缩小（Gulcehre 等 2023）。这为下一课的停止条件埋下伏笔。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把回路写成分布的迭代：设第 \\(t\\) 轮策略为 \\(\\pi_t\\)，选择算子为 \\(\\mathcal{F}\\)（过滤与验证），训练数据测度 \\(\\mu_{t+1}=\\mathcal{F}\\,\\pi_{t+1}\\)，训练把下一轮策略拉向 \\(\\mathcal{F}\\) 的支撑。回路里没有独立外部参照时，\\(\\pi\\) 既是数据的生产者又是消费者，\\(\\mathcal{F}\\) 的每一处系统性误差都会被反复写进权重——这是本单元坍缩课与验证器瓶颈课的共同起点。与<a href="/llm/self-play-lm">自博弈</a>的关系：自博弈是把「对手」也换成旧策略的闭环特例，支付来自对弈或校验；与 <a href="/llm/rlvr">RLVR</a> 的关系：在线 RL 用即时推理集群换流程紧凑，SFT 循环用离线批次换工程简单。记账口径：每轮新增「通过且新颖」的样本数是毛收入，多样性收缩与验证误差是两项折旧；只看通过率不看新颖度，会把复读当进步。</p><p><span class="marginnote">「\\(\\pi\\) 既是生产者又是消费者」可以想象成学生自己出题、自己判卷、再照着卷子复习：判卷标准哪里偏了，复习方向就跟着偏，下一轮的题与答案进一步偏——没有外部老师对答案，偏误会自我强化。</span></p><p>回路每转一圈，资产与损耗同时在涨，两边必须分开记：</p>',9)),(A(),B(o,null,{default:a(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOP%5B%22%E5%9B%9E%E8%B7%AF%E6%AF%8F%E8%BD%AC%E4%B8%80%E5%9C%88%22%5D%20--%3E%20A%5B%22%E8%B5%84%E4%BA%A7%E4%BE%A7%22%5D%0A%20%20LOOP%20--%3E%20B%5B%22%E6%8D%9F%E8%80%97%E4%BE%A7%22%5D%0A%20%20A%20--%3E%20A1%5B%22on-policy%20%E8%A6%86%E7%9B%96%EF%BC%9A%E5%AF%B9%E9%BD%90%E5%BD%93%E5%89%8D%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E5%B7%B2%E9%AA%8C%E8%AF%81%E8%A7%A3%E6%B3%95%EF%BC%9A%E5%8F%AF%E5%A4%8D%E7%94%A8%E7%9A%84%E7%A1%AE%E5%AE%9A%E8%B5%84%E4%BA%A7%22%5D%0A%20%20A%20--%3E%20A3%5B%22%E5%A4%B1%E8%B4%A5%E6%A0%B7%E6%9C%AC%EF%BC%9A%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%E7%9A%84%E8%B4%9F%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E8%BF%87%E6%BB%A4%E6%94%B6%E7%BC%A9%EF%BC%9A%E5%A4%9A%E6%A0%B7%E6%80%A7%E9%80%90%E8%BD%AE%E4%B8%8B%E9%99%8D%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E9%AA%8C%E8%AF%81%E8%AF%AF%E5%B7%AE%EF%BC%9A%E8%A2%AB%E4%BC%98%E5%8C%96%E5%8E%8B%E5%8A%9B%E6%94%BE%E5%A4%A7%22%5D%0A%20%20B%20--%3E%20B3%5B%22%E8%A6%86%E7%9B%96%E9%9B%86%E4%B8%AD%EF%BC%9A%E5%85%A8%E5%AF%B9%E5%85%A8%E9%94%99%E7%BB%84%E5%A4%B1%E5%8E%BB%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只立结构：回路何时该停是下一课；不停轮会发生什么（尾部丢失、熵收缩）是坍缩课；选择算子自身的误差如何变成策略偏移是验证器瓶颈课；域与判据的设计权衡是 RLVR 设计空间课；出题侧的合成与自举收在本单元末课。裁判与选手同一模型的自奖励属于下一单元；预训练配比里的合成（<a href="/llm/textbook-synthetic">教科书式合成</a>、<a href="/llm/synthetic-pretrain">合成数据在预训练中的位置</a>）已有专课，这里不重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自训练回路四站：生成、过滤与验证、训练、再生成；单轮 RFT 与多轮闭环性质不同。</li><li>资产：on-policy 覆盖、可复用的已验证解法、失败样本的负梯度；损耗：多样性收缩、验证误差放大、覆盖向中间难度集中。</li><li>闭环是分布的迭代映射，选择算子的系统性误差会被再生成放大。</li><li>记账要看「通过且新颖」的增量，不能只看通过率。</li><li>出处：Zelikman 等 STaR；Gulcehre 等 ReST-EM；单点机制见 RLVR 与自博弈各课。</li></ul>',4))])}const T=i(p,[["render",m]]);export{c as __pageData,T as default};
